    Bug 2022206 - Avoid copying subFolders in EwsFolder::EmptyTrash() - for performance reasons. r=mkmelin


    GCC-15 issues warning to avoid copying for peformance reason reason in
    a couple of places.

    Differential Revision: https://phabricator.services.mozilla.com/D286880

diff --git a/mailnews/protocols/exchange/src/EwsFolder.cpp b/mailnews/protocols/exchange/src/EwsFolder.cpp
index c20bba5ace6..7fc1d41d610 100644
--- a/mailnews/protocols/exchange/src/EwsFolder.cpp
+++ b/mailnews/protocols/exchange/src/EwsFolder.cpp
@@ -1143,7 +1143,7 @@ NS_IMETHODIMP EwsFolder::EmptyTrash(nsIUrlListener* aListener) {
   rv = trashFolder->GetSubFolders(subFolders);
   NS_ENSURE_SUCCESS(rv, rv);
   nsTArray<nsCString> subFolderIds(subFolders.Length());
-  for (const auto f : subFolders) {
+  for (const auto& f : subFolders) {
     nsCString ewsId;
     rv = f->GetStringProperty(kEwsIdProperty, ewsId);
     NS_ENSURE_SUCCESS(rv, rv);
@@ -1179,7 +1179,7 @@ NS_IMETHODIMP EwsFolder::EmptyTrash(nsIUrlListener* aListener) {
         rv = trashFolder->GetSubFolders(subFolders);
         NS_ENSURE_SUCCESS(rv, rv);

-        for (const auto f : subFolders) {
+        for (const auto& f : subFolders) {
           rv = trashFolder->PropagateDelete(f, true);
           NS_ENSURE_SUCCESS(rv, rv);
         }
